import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{B as r,c as e,f as l,q as n,D as p,Q as o,g as i}from"./chunks/runtime-core.esm-bundler.BPXnTuTE.js";const d="/assets/hydration.Cc6xMylS.png",c="/assets/hydration-1.B5XuLh0o.png",g="/assets/hydration-2.DZ4_fHEq.png",M=JSON.parse('{"title":"SSR 服务端渲染的原理","description":"","frontmatter":{},"headers":[],"relativePath":"column/Next/基础/SSR 服务端渲染的原理.md","filePath":"column/Next/基础/SSR 服务端渲染的原理.md","lastUpdated":1785136738000}'),S={name:"column/Next/基础/SSR 服务端渲染的原理.md"};function b(u,s,h,m,T,R){const a=r("ArticleMetadata");return l(),e("div",null,[s[0]||(s[0]=n("h1",{id:"ssr-服务端渲染的原理",tabindex:"-1"},[i("SSR 服务端渲染的原理 "),n("a",{class:"header-anchor",href:"#ssr-服务端渲染的原理","aria-label":'Permalink to "SSR 服务端渲染的原理"'},"​")],-1)),p(a),s[1]||(s[1]=o('<nav class="table-of-contents"><ul><li><a href="#一、ssr-的完整执行流程">一、SSR 的完整执行流程</a></li><li><a href="#二、核心概念-什么是-水合-hydration">二、核心概念：什么是&quot;水合&quot;（Hydration）？</a></li><li><a href="#三、csr-与-ssr-核心对比">三、CSR 与 SSR 核心对比</a></li><li><a href="#四、为什么感觉ssr并没有很快">四、为什么感觉SSR并没有很快？</a><ul><li><a href="#_1-核心瓶颈转移-从-客户端忙-变成-服务端忙">1. 核心瓶颈转移：从“客户端忙”变成“服务端忙”</a></li><li><a href="#_2-感觉慢-的四个具体原因">2. “感觉慢”的四个具体原因：</a></li></ul></li><li><a href="#五、ssr-页面初始化的资源加载顺序">五、SSR 页面初始化的资源加载顺序</a><ul><li><a href="#_1-ssr-页面初始化的资源加载全顺序">1. SSR 页面初始化的资源加载全顺序</a></li><li><a href="#_2-4-个非常容易混淆的加载细节">2. 4 个非常容易混淆的加载细节</a></li><li><a href="#_3-总结一览表-按执行先后顺序">3. 总结一览表（按执行先后顺序）</a></li></ul></li><li><a href="#六、总结-什么时候用-ssr-才是真正-变快">六、总结：什么时候用 SSR 才是真正“变快”？</a></li></ul></nav><blockquote><p>理解 SSR（Server-Side Rendering，服务端渲染）的核心，其实只需要记住一句话：<strong>将网页的 HTML 结构生成过程从&quot;用户的浏览器&quot;搬到了&quot;后端的服务器&quot;。</strong></p></blockquote><p>在单页面应用（SPA/CSR）时代，服务器只返回一个几乎为空的 HTML 壳子（如 <code>&lt;div id=&quot;app&quot;&gt;&lt;/div&gt;</code>）和一堆 JavaScript 文件，页面内容全靠浏览器运行 JS 动态渲染。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;div id=&quot;app&quot;&gt;&lt;/div&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>而 <strong>SSR 则是服务器直接拼接好包含完整内容的 HTML 字符串发送给浏览器，浏览器拿到就能直接显示。</strong></p><p><img src="'+d+'" alt="" loading="lazy"></p><h2 id="一、ssr-的完整执行流程" tabindex="-1">一、SSR 的完整执行流程 <a class="header-anchor" href="#一、ssr-的完整执行流程" aria-label="Permalink to &quot;一、SSR 的完整执行流程&quot;">​</a></h2><p>现代前端框架（如 React / Vue）的 SSR 并不是简单的传统模板引擎，它经历了一个关键的 <strong>&quot;服务端拼接 HTML + 客户端水合（Hydration）&quot;</strong> 的过程：</p><ol><li><p><strong>用户发起请求:</strong> 用户在浏览器输入网址或点击链接，发送 HTTP 请求到 Node.js 服务端。</p></li><li><p><strong>服务端数据预获取 (Data Fetching):</strong> 服务端路由匹配到当前页面后，在 Node.js 环境中提前调用 API 接口或查询数据库，获取页面所需的初始化数据。</p></li><li><p><strong>渲染组件为 HTML 字符串:（renderToString）</strong> 服务端将获取到的数据注入前端组件（如 React / Vue），使用框架提供的 <code>renderToString()</code> 等 API，把虚拟 DOM 结构转换成真实的 <strong>HTML 纯文本字符串</strong>。</p></li><li><p><strong>返回 HTML + 预挂载数据:</strong> 服务端将渲染好的 HTML、样式表（CSS）以及一小段脱水数据（Dehydrated Data，如 <code>window.__INITIAL_STATE__</code>）打包返回给浏览器。<strong>此时浏览器收到响应即可立即把页面绘制出来（首屏可见，FCP）</strong>。</p></li><li><p><strong>客户端&quot;水合/注水&quot; (Hydration):</strong> 浏览器下载并执行打包好的 JavaScript Bundle，框架（React/Vue）在客户端重新扫描现有 DOM，将事件监听器（如点击、输入事件）绑定到静态 DOM 节点上，把&quot;干瘪&quot;的静态 HTML 激活为可交互的动态应用。</p></li></ol><h2 id="二、核心概念-什么是-水合-hydration" tabindex="-1">二、核心概念：什么是&quot;水合&quot;（Hydration）？ <a class="header-anchor" href="#二、核心概念-什么是-水合-hydration" aria-label="Permalink to &quot;二、核心概念：什么是&quot;水合&quot;（Hydration）？&quot;">​</a></h2><p>初学者最容易困惑的地方在于：<strong>既然服务器已经把 HTML 渲染好了，为什么还需要下载 JS 并在客户端再运行一遍？</strong></p><blockquote><p><strong>比喻说明：</strong> 服务端传过来的 HTML 就像一具 <strong>&quot;干瘪的塑像&quot;</strong> ——它有完整的外形（DOM 结构和文字内容），但缺乏灵魂（点击没反应、没有状态变化）。 客户端下载 JS 后进行的 <strong>Hydration（注水/水合）</strong>，就像是给塑像注入水分和血液。JS 将事件绑定回现有的 DOM 上，让它变成活生生、可交互的组件。</p></blockquote><p>如果省略了 Hydration 阶段，用户虽然能看到页面，但点击按钮、切换 Tab 或提交表单都不会有任何响应。</p><p>详细介绍见这篇文章：<a href="/column/Next/基础/什么是RSC渲染#六、什么是水合-hydration">什么是水合-hydration</a></p><h2 id="三、csr-与-ssr-核心对比" tabindex="-1">三、CSR 与 SSR 核心对比 <a class="header-anchor" href="#三、csr-与-ssr-核心对比" aria-label="Permalink to &quot;三、CSR 与 SSR 核心对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>CSR（客户端渲染）</th><th>SSR（服务端渲染）</th></tr></thead><tbody><tr><td><strong>首屏渲染速度 (FCP)</strong></td><td>较慢（需先下载并执行庞大的 JS 文件）</td><td><strong>极快</strong>（直接拿到完整 HTML 展示）</td></tr><tr><td><strong>SEO 搜索引擎优化</strong></td><td>较差（爬虫拿到的是空 HTML 壳）</td><td><strong>友好</strong>（爬虫可以直接爬取 HTML 内容）</td></tr><tr><td><strong>服务器负载 (CPU)</strong></td><td>极低（主要压力在用户浏览器）</td><td><strong>较高</strong>（每条请求都需要服务器计算拼接 HTML）</td></tr><tr><td><strong>开发复杂度</strong></td><td>简单（无需处理跨端代码与生命周期）</td><td>较复杂（需注意 <code>window/document</code> 在服务端不存在）</td></tr></tbody></table><h2 id="四、为什么感觉ssr并没有很快" tabindex="-1">四、为什么感觉SSR并没有很快？ <a class="header-anchor" href="#四、为什么感觉ssr并没有很快" aria-label="Permalink to &quot;四、为什么感觉SSR并没有很快？&quot;">​</a></h2><p><strong>SSR 服务端渲染的详细执行流程图</strong></p><p><img src="'+c+`" alt="" loading="lazy"></p><p>在实际开发中，SSR 的“快”是<strong>有条件的</strong>，而“慢”通常是<strong>普遍且由于以下几个关键因素导致的</strong>。</p><p>我们用 CSR 和 SSR 的耗时结构对比来解释：</p><h3 id="_1-核心瓶颈转移-从-客户端忙-变成-服务端忙" tabindex="-1">1. 核心瓶颈转移：从“客户端忙”变成“服务端忙” <a class="header-anchor" href="#_1-核心瓶颈转移-从-客户端忙-变成-服务端忙" aria-label="Permalink to &quot;1. 核心瓶颈转移：从“客户端忙”变成“服务端忙”&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>核心瓶颈 (慢在哪里)</th><th>表现</th></tr></thead><tbody><tr><td><strong>CSR</strong></td><td><strong>客户端 JS 执行</strong> (耗尽用户手机的 CPU)</td><td>用户看到一个白屏/Loading 很久，直到 JS 执行完才显示内容。</td></tr><tr><td><strong>SSR</strong></td><td><strong>服务端网络请求 (TTI) + 服务端计算</strong></td><td>浏览器发送请求后，<strong>转圈圈（等待响应）很久</strong>，然后页面突然一下子完整显示出来。</td></tr></tbody></table><h3 id="_2-感觉慢-的四个具体原因" tabindex="-1">2. “感觉慢”的四个具体原因： <a class="header-anchor" href="#_2-感觉慢-的四个具体原因" aria-label="Permalink to &quot;2. “感觉慢”的四个具体原因：&quot;">​</a></h3><h5 id="a-服务端-api-请求的级联延迟-ttfb-增加" tabindex="-1">A. 服务端 API 请求的级联延迟 (TTFB 增加) <a class="header-anchor" href="#a-服务端-api-请求的级联延迟-ttfb-增加" aria-label="Permalink to &quot;A. 服务端 API 请求的级联延迟 (TTFB 增加)&quot;">​</a></h5><p>这是 <strong>SSR 慢的首要原因</strong>。</p><ul><li><strong>CSR:</strong> 浏览器先拿到 HTML，再去请求数据。虽然白屏，但浏览器至少响应了。</li><li><strong>SSR:</strong> Node.js 服务器<strong>必须等待所有的初始化数据</strong>请求（可能包含 3 个 API 调用）都完成后，才能开始生成 HTML。如果某个后端 API 很慢，你的 SSR 服务端就会被<strong>阻塞</strong>，浏览器就会一直等待，表现为<strong>首字节时间 (TTFB) 极高</strong>，也就是用户看到的“转圈圈等待响应”阶段极长。</li></ul><h5 id="b-服务端-cpu-密集型操作-rendertostring" tabindex="-1">B. 服务端 CPU 密集型操作 (renderToString) <a class="header-anchor" href="#b-服务端-cpu-密集型操作-rendertostring" aria-label="Permalink to &quot;B. 服务端 CPU 密集型操作 (renderToString)&quot;">​</a></h5><p>前端组件通常包含大量的循环、判断和 DOM 结构。在服务端使用 <code>renderToString</code> 把这一大堆虚拟 DOM 节点计算成静态字符串是非常<strong>消耗 CPU 资源</strong>的。在高并发下，Node.js 的单线程特性很容易成为瓶颈，导致每个请求的处理时间都被拉长。</p><h5 id="c-激活-hydration-的成本" tabindex="-1">C. 激活 (Hydration) 的成本 <a class="header-anchor" href="#c-激活-hydration-的成本" aria-label="Permalink to &quot;C. 激活 (Hydration) 的成本&quot;">​</a></h5><p>虽然 SSR 提前给了用户 HTML 内容（FCP 快），但它并没有省去客户端的 JS 执行成本。</p><ul><li><strong>CSR:</strong> JS 负责数据请求、DOM 生成和事件绑定。</li><li><strong>SSR:</strong> 客户端 JS 需要执行<strong>一遍几乎完全一样的组件渲染流程</strong>（只是不重新生成 DOM，而是只绑定事件）。如果你的 JS Bundle 依然很大，用户即使看到了内容，依然需要等待 JS 下载并执行完（激活）后才能点击。<strong>从内容可见 (FCP) 到完全可交互 (TTI) 的这段时间差，用户体验实际上是变差的。</strong></li></ul><h5 id="d-缺乏合适的网络缓存" tabindex="-1">D. 缺乏合适的网络缓存 <a class="header-anchor" href="#d-缺乏合适的网络缓存" aria-label="Permalink to &quot;D. 缺乏合适的网络缓存&quot;">​</a></h5><p>CSR 的核心资源（HTML 壳、JS、CSS）都是静态文件，可以完美利用 CDN 强缓存。 SSR 的 HTML 是动态生成的，针对不同用户甚至不同时间点内容都不同。如果你的 SSR 服务端没有做好 HTML 的缓存策略（例如：只对非登录用户缓存 1 分钟），每次请求都要全流程计算一遍，那速度必然远慢于直接读取 CDN 缓存文件。</p><h2 id="五、ssr-页面初始化的资源加载顺序" tabindex="-1">五、SSR 页面初始化的资源加载顺序 <a class="header-anchor" href="#五、ssr-页面初始化的资源加载顺序" aria-label="Permalink to &quot;五、SSR 页面初始化的资源加载顺序&quot;">​</a></h2><p>这个细节非常关键！很多人搞不懂 SSR，就是因为没理清<strong>浏览器在“初始化”那一瞬间，HTML、CSS、JS 和静态资源（如图片、字体）到底是按什么顺序加载和执行的</strong>。</p><p>我们用一张<strong>浏览器时间轴流程图</strong>，把页面从“一片空白”到“完全能点”的所有资源加载顺序一次性说清楚。</p><h3 id="_1-ssr-页面初始化的资源加载全顺序" tabindex="-1">1. SSR 页面初始化的资源加载全顺序 <a class="header-anchor" href="#_1-ssr-页面初始化的资源加载全顺序" aria-label="Permalink to &quot;1. SSR 页面初始化的资源加载全顺序&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入 URL</span></span>
<span class="line"><span>   │</span></span>
<span class="line"><span>   ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. [HTML 文本文件]                                     │</span></span>
<span class="line"><span>│    服务端返回的纯文本。                                │</span></span>
<span class="line"><span>│    浏览器拿到后，一边解析 DOM 结构，一边发现后续资源。   │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 2. [关键 CSS 样式文件 / &lt;style&gt; 标签]                 │</span></span>
<span class="line"><span>│    【最高优先级阻断】                                  │</span></span>
<span class="line"><span>│    浏览器停止渲染页面，必须先下载并解析 CSS，           │</span></span>
<span class="line"><span>│    确保页面出来时带样式，不会“乱码/排版错乱”。         │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 3. [首屏静态资源：首屏图片 / 字体]                    │</span></span>
<span class="line"><span>│    【与 CSS 几乎并行/稍后下载】                        │</span></span>
<span class="line"><span>│    HTML 里的 &lt;img&gt; 标签和字体文件开始下载。            │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>                  🌟 节点一：首屏呈现 (FCP)</span></span>
<span class="line"><span>          【用户眼睛看到了完整页面、文字和样式】</span></span>
<span class="line"><span>          【但此时页面是“假”的，点击任何按钮都没反应！】</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 4. [客户端 JS 打包文件 (Bundle)]                      │</span></span>
<span class="line"><span>│    【通常带 defer 或在 &lt;/body&gt; 前】                   │</span></span>
<span class="line"><span>│    SSR 虽然生成了 HTML，但仍需要下载打包好的 JS 文件。  │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 5. [JS 代码解析与执行 + 触发水合 (Hydration)]          │</span></span>
<span class="line"><span>│    浏览器在本地运行 JS，扫描已存在的 HTML DOM 节点，   │</span></span>
<span class="line"><span>│    把点击、输入等“事件监听器”绑定上去。                │</span></span>
<span class="line"><span>└──────────────────────────┬─────────────────────────────┘</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>                  🌟 节点二：完全可交互 (TTI)</span></span>
<span class="line"><span>            【水合完成！页面变成了活的，点击有响应了】</span></span>
<span class="line"><span>                           │</span></span>
<span class="line"><span>                           ▼</span></span>
<span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 6. [非首屏/次要静态资源]                              │</span></span>
<span class="line"><span>│    【最低优先级】                                      │</span></span>
<span class="line"><span>│    屏外图片（Lazy-load）、埋点统计 JS、广告脚本等。    │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br><span class="line-number">47</span><br><span class="line-number">48</span><br><span class="line-number">49</span><br><span class="line-number">50</span><br><span class="line-number">51</span><br><span class="line-number">52</span><br><span class="line-number">53</span><br></div></div><h3 id="_2-4-个非常容易混淆的加载细节" tabindex="-1">2. 4 个非常容易混淆的加载细节 <a class="header-anchor" href="#_2-4-个非常容易混淆的加载细节" aria-label="Permalink to &quot;2. 4 个非常容易混淆的加载细节&quot;">​</a></h3><h4 id="_1-html-与-css-css-会-卡住-页面展示" tabindex="-1">1. HTML 与 CSS：CSS 会“卡住”页面展示 <a class="header-anchor" href="#_1-html-与-css-css-会-卡住-页面展示" aria-label="Permalink to &quot;1. HTML 与 CSS：CSS 会“卡住”页面展示&quot;">​</a></h4><ul><li><strong>细节</strong>：HTML 拿到了，浏览器<strong>不会</strong>立刻把字打印在屏幕上。如果 <code>&lt;head&gt;</code> 里有外部 CSS 文件，浏览器会<strong>等 CSS 下载并解析完</strong>（生成 CSSOM）之后，才把带着漂亮的样式的页面一次性画出来。</li><li><strong>为什么</strong>：如果 CSS 慢了，用户就会看到网页先是黑白乱码，突然闪烁一下变成漂亮页面（Flash of Unstyled Content，简称 FOUT），体验极差。</li></ul><h4 id="_2-html-与-js-js-是什么时候下载的" tabindex="-1">2. HTML 与 JS：JS 是什么时候下载的？ <a class="header-anchor" href="#_2-html-与-js-js-是什么时候下载的" aria-label="Permalink to &quot;2. HTML 与 JS：JS 是什么时候下载的？&quot;">​</a></h4><ul><li><strong>细节</strong>：在 SSR 中，JS 文件（React/Vue 客户端代码）通常放在 HTML 的最底部（<code>&lt;/body&gt;</code> 之前），或者加上了 <code>defer</code> 属性。</li><li><strong>为什么</strong>：<strong>不能让 JS 阻塞首屏渲染！</strong> 浏览器会先画出 HTML 内容（让用户看到字），然后<strong>在后台默默下载 JS</strong>。</li></ul><h4 id="_3-首屏可看-vs-页面可点-它们中间有一个-时间差" tabindex="-1">3. 首屏可看 vs 页面可点：它们中间有一个“时间差” <a class="header-anchor" href="#_3-首屏可看-vs-页面可点-它们中间有一个-时间差" aria-label="Permalink to &quot;3. 首屏可看 vs 页面可点：它们中间有一个“时间差”&quot;">​</a></h4><ul><li><p><strong>这是 SSR 特有的现象</strong>：</p></li><li><p><strong>节点一（FCP）</strong>：HTML + CSS 处理完，<strong>页面出来了</strong>。</p></li><li><p><strong>节点二（TTI）</strong>：JS 下载完并跑完“水合（Hydration）”，<strong>页面才能点</strong>。</p></li><li><p><strong>隐患</strong>：如果你的 JS 文件非常大，或者手机性能很差，这两个节点之间可能会相隔 <strong>2~3 秒</strong>。在这期间，用户看到按钮去点，却<strong>完全没有反应</strong>，会以为网页卡死了。</p></li></ul><h4 id="_4-图片等静态资源-不阻塞-dom-但影响整体体验" tabindex="-1">4. 图片等静态资源：不阻塞 DOM，但影响整体体验 <a class="header-anchor" href="#_4-图片等静态资源-不阻塞-dom-但影响整体体验" aria-label="Permalink to &quot;4. 图片等静态资源：不阻塞 DOM，但影响整体体验&quot;">​</a></h4><ul><li><strong>细节</strong>：HTML 解析到 <code>&lt;img&gt;</code> 时会发起图片下载，它<strong>不会阻塞</strong> HTML 解析，也不会阻塞 JS 执行。</li><li><strong>优化</strong>：现代 SSR 通常会对<strong>首屏图片</strong>做特殊处理（比如设置 <code>priority</code> 预加载），而对<strong>首屏之外（往下滑动才能看到）的图片</strong>加上 <code>loading=&quot;lazy&quot;</code>（懒加载），等用户滑动到了再去下载。</li></ul><p><strong>如图所示</strong>：</p><p><img src="`+g+'" alt="" loading="lazy"></p><h3 id="_3-总结一览表-按执行先后顺序" tabindex="-1">3. 总结一览表（按执行先后顺序） <a class="header-anchor" href="#_3-总结一览表-按执行先后顺序" aria-label="Permalink to &quot;3. 总结一览表（按执行先后顺序）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>序号</th><th>资源/动作</th><th>浏览器在干什么</th><th>用户能感知到什么</th></tr></thead><tbody><tr><td><strong>1</strong></td><td><strong>HTML 文本</strong></td><td>建立连接，接收服务器发来的纯文本</td><td>标签页开始转圈，白屏</td></tr><tr><td><strong>2</strong></td><td><strong>CSS 样式</strong></td><td>下载并解析样式规则</td><td>依然白屏（被 CSS 阻塞）</td></tr><tr><td><strong>3</strong></td><td><strong>渲染首屏</strong></td><td>结合 HTML + CSS 生成渲染树</td><td><strong>整页刷出！眼睛看到内容 (FCP)</strong></td></tr><tr><td><strong>4</strong></td><td><strong>JS Bundle</strong></td><td>在后台下载 JavaScript 脚本</td><td>能看内容，但<strong>点击无响应</strong></td></tr><tr><td><strong>5</strong></td><td><strong>水合 (Hydration)</strong></td><td>运行 JS，把点击事件绑定给 HTML DOM</td><td>页面突然“活了”</td></tr><tr><td><strong>6</strong></td><td><strong>交互就绪</strong></td><td>激活全部绑定</td><td><strong>完全可以正常操作 (TTI)</strong></td></tr></tbody></table><h2 id="六、总结-什么时候用-ssr-才是真正-变快" tabindex="-1">六、总结：什么时候用 SSR 才是真正“变快”？ <a class="header-anchor" href="#六、总结-什么时候用-ssr-才是真正-变快" aria-label="Permalink to &quot;六、总结：什么时候用 SSR 才是真正“变快”？&quot;">​</a></h2><p>SSR 不是为了解决“所有性能问题”，它主要解决两个特定痛点：</p><ol><li><strong>SEO (搜索引擎优化)</strong>: 爬虫必须直接拿到完整 HTML。</li><li><strong>首屏可见时间 (FCP) 极其重要</strong>：在弱网环境（如 3G）或低端设备下，用户无法等待庞大的 JS Bundle 下载。SSR 让他们能更快看到内容，心理感觉“变快了”，即使交互依然需要等待。</li></ol><p><strong>如果你的应用：</strong></p><ul><li>不需要 SEO（例如：内部系统、ERP）。</li><li>主要数据都在登录后获取。</li><li>JS Bundle 并不算巨大（&lt; 300KB minified）。</li></ul><p><strong>那么继续使用 CSR 可能会获得更好的用户体验和更低的开发/服务器成本。</strong> 不要为了 SSR 而 SSR。</p>',58))])}const C=t(S,[["render",b]]);export{M as __pageData,C as default};
